import{_ as e,o as i,c as r,ag as n}from"./chunks/framework.DKalukzk.js";const h=JSON.parse('{"title":"Grille d’évaluation — TP4","description":"Grille critériée — Présentation PowerPoint : enjeux du métier en informatique","frontmatter":{"title":"Grille d’évaluation — TP4","description":"Grille critériée — Présentation PowerPoint : enjeux du métier en informatique","aside":true},"headers":[],"relativePath":"grilles/grille-tp4-ppt-ethique.md","filePath":"grilles/grille-tp4-ppt-ethique.md"}'),a={name:"grilles/grille-tp4-ppt-ethique.md"};function s(o,t,d,l,u,c){return i(),r("div",null,[...t[0]||(t[0]=[n('<h1 id="grille-d-evaluation-—-tp4" tabindex="-1">Grille d’évaluation — TP4 <a class="header-anchor" href="#grille-d-evaluation-—-tp4" aria-label="Permalink to &quot;Grille d’évaluation — TP4&quot;">​</a></h1><p><strong>Présentation PowerPoint : enjeux du métier en informatique</strong></p><blockquote><p><strong>Échelle descriptive</strong><br><strong>Excellent = 100 %</strong> · <strong>Bien = 80 %</strong> · <strong>Suffisant = 60 %</strong> · <strong>Insuffisant = 40 %</strong> · <strong>Invalide = 0 %</strong></p></blockquote><hr><h2 id="partie-equipe-—-diaporama-et-contenu-80" tabindex="-1">Partie équipe — Diaporama et contenu (80 %) <a class="header-anchor" href="#partie-equipe-—-diaporama-et-contenu-80" aria-label="Permalink to &quot;Partie équipe — Diaporama et contenu (80 %)&quot;">​</a></h2><h3 id="_1-problematique-10" tabindex="-1">1) Problématique (10 %) <a class="header-anchor" href="#_1-problematique-10" aria-label="Permalink to &quot;1) Problématique (10 %)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Niveau</th><th>Description</th><th>Note</th></tr></thead><tbody><tr><td><strong>Excellent</strong></td><td>Situation réaliste et précise, problème clairement formulé, parties concernées identifiées avec justesse.</td><td>100 %</td></tr><tr><td><strong>Bien</strong></td><td>Situation claire et pertinente, mais certains éléments (contexte, parties concernées) manquent de précision.</td><td>80 %</td></tr><tr><td><strong>Suffisant</strong></td><td>Problématique présente mais trop générale, imprécise ou incomplète.</td><td>60 %</td></tr><tr><td><strong>Insuffisant</strong></td><td>Problématique confuse, mal définie, ou ne permet pas d’orienter l’analyse.</td><td>40 %</td></tr><tr><td><strong>Invalide</strong></td><td>Problématique absente ou hors sujet.</td><td>0 %</td></tr></tbody></table><hr><h3 id="_2-analyse-faits-causes-risques-incertitudes-points-de-vue-20" tabindex="-1">2) Analyse (faits, causes, risques, incertitudes, points de vue) (20 %) <a class="header-anchor" href="#_2-analyse-faits-causes-risques-incertitudes-points-de-vue-20" aria-label="Permalink to &quot;2) Analyse (faits, causes, risques, incertitudes, points de vue) (20 %)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Niveau</th><th>Description</th><th>Note</th></tr></thead><tbody><tr><td><strong>Excellent</strong></td><td>Analyse solide et structurée; faits pertinents; causes/risques expliqués; zones d’incertitude reconnues; au moins deux points de vue présentés de façon équitable.</td><td>100 %</td></tr><tr><td><strong>Bien</strong></td><td>Analyse pertinente et globalement structurée; deux points de vue présents, mais certaines nuances ou justifications manquent.</td><td>80 %</td></tr><tr><td><strong>Suffisant</strong></td><td>Analyse surtout descriptive; arguments partiels; points de vue peu développés ou déséquilibrés.</td><td>60 %</td></tr><tr><td><strong>Insuffisant</strong></td><td>Analyse superficielle; faits faibles; risques/causes peu liés au cas; points de vue incomplets.</td><td>40 %</td></tr><tr><td><strong>Invalide</strong></td><td>Analyse absente ou ne répondant pas à la consigne.</td><td>0 %</td></tr></tbody></table><hr><h3 id="_3-cadre-legal-ethique-15" tabindex="-1">3) Cadre légal / éthique (15 %) <a class="header-anchor" href="#_3-cadre-legal-ethique-15" aria-label="Permalink to &quot;3) Cadre légal / éthique (15 %)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Niveau</th><th>Description</th><th>Note</th></tr></thead><tbody><tr><td><strong>Excellent</strong></td><td>Cadre applicable présenté avec rigueur (règles, obligations, bonnes pratiques); principes éthiques pertinents clairement reliés au cas (confidentialité, transparence, équité, responsabilité, etc.).</td><td>100 %</td></tr><tr><td><strong>Bien</strong></td><td>Cadre globalement pertinent; liens avec le cas présents, mais certaines notions sont survolées ou manquent de précision.</td><td>80 %</td></tr><tr><td><strong>Suffisant</strong></td><td>Cadre mentionné mais partiellement relié au cas; plusieurs éléments restent généraux.</td><td>60 %</td></tr><tr><td><strong>Insuffisant</strong></td><td>Cadre peu pertinent, confus, ou très incomplet; peu de liens avec la situation.</td><td>40 %</td></tr><tr><td><strong>Invalide</strong></td><td>Cadre légal/éthique absent.</td><td>0 %</td></tr></tbody></table><hr><h3 id="_4-consequences-humaines-organisationnelles-financieres-juridiques-reputationnelles-10" tabindex="-1">4) Conséquences (humaines, organisationnelles, financières, juridiques, réputationnelles) (10 %) <a class="header-anchor" href="#_4-consequences-humaines-organisationnelles-financieres-juridiques-reputationnelles-10" aria-label="Permalink to &quot;4) Conséquences (humaines, organisationnelles, financières, juridiques, réputationnelles) (10 %)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Niveau</th><th>Description</th><th>Note</th></tr></thead><tbody><tr><td><strong>Excellent</strong></td><td>Conséquences bien analysées et nuancées; comparaison claire entre « agir » et « ne pas agir »; impacts variés et plausibles.</td><td>100 %</td></tr><tr><td><strong>Bien</strong></td><td>Conséquences pertinentes et plausibles; certains impacts manquent de profondeur ou de variété.</td><td>80 %</td></tr><tr><td><strong>Suffisant</strong></td><td>Conséquences présentes, mais partielles, génériques ou peu justifiées.</td><td>60 %</td></tr><tr><td><strong>Insuffisant</strong></td><td>Conséquences vagues, peu liées au cas, ou contenant des incohérences.</td><td>40 %</td></tr><tr><td><strong>Invalide</strong></td><td>Conséquences absentes.</td><td>0 %</td></tr></tbody></table><hr><h3 id="_5-position-de-l-equipe-recommandation-justification-15" tabindex="-1">5) Position de l’équipe (recommandation + justification) (15 %) <a class="header-anchor" href="#_5-position-de-l-equipe-recommandation-justification-15" aria-label="Permalink to &quot;5) Position de l’équipe (recommandation + justification) (15 %)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Niveau</th><th>Description</th><th>Note</th></tr></thead><tbody><tr><td><strong>Excellent</strong></td><td>Position claire et assumée; recommandation nuancée (quoi faire et limites); justification convaincante (2–4 arguments solides) directement liée à l’analyse et au cadre.</td><td>100 %</td></tr><tr><td><strong>Bien</strong></td><td>Position claire; arguments pertinents, mais certaines justifications manquent de liens explicites avec l’analyse/cadre.</td><td>80 %</td></tr><tr><td><strong>Suffisant</strong></td><td>Position présente, mais trop générale; arguments corrects mais peu développés ou répétitifs.</td><td>60 %</td></tr><tr><td><strong>Insuffisant</strong></td><td>Position floue ou contradictoire; arguments faibles ou peu reliés au cas.</td><td>40 %</td></tr><tr><td><strong>Invalide</strong></td><td>Aucune position (présentation purement descriptive).</td><td>0 %</td></tr></tbody></table><hr><h3 id="_6-qualite-du-diaporama-structure-lisibilite-synthese-visuels-coherence-10" tabindex="-1">6) Qualité du diaporama (structure, lisibilité, synthèse, visuels, cohérence) (10 %) <a class="header-anchor" href="#_6-qualite-du-diaporama-structure-lisibilite-synthese-visuels-coherence-10" aria-label="Permalink to &quot;6) Qualité du diaporama (structure, lisibilité, synthèse, visuels, cohérence) (10 %)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Niveau</th><th>Description</th><th>Note</th></tr></thead><tbody><tr><td><strong>Excellent</strong></td><td>Diaporama très lisible et cohérent; peu de texte; titres/repères clairs; visuels utiles; structure conforme et efficace; style uniforme.</td><td>100 %</td></tr><tr><td><strong>Bien</strong></td><td>Diaporama lisible et cohérent; quelques diapositives trop chargées ou quelques incohérences mineures.</td><td>80 %</td></tr><tr><td><strong>Suffisant</strong></td><td>Diaporama compréhensible, mais trop textuel ou inégal; structure ou cohérence perfectible.</td><td>60 %</td></tr><tr><td><strong>Insuffisant</strong></td><td>Diaporama difficile à lire; surcharge de texte; visuels peu utiles; incohérences fréquentes.</td><td>40 %</td></tr><tr><td><strong>Invalide</strong></td><td>Diaporama absent ou non utilisable.</td><td>0 %</td></tr></tbody></table><hr><h2 id="partie-individuelle-—-presentation-orale-20" tabindex="-1">Partie individuelle — Présentation orale (20 %) <a class="header-anchor" href="#partie-individuelle-—-presentation-orale-20" aria-label="Permalink to &quot;Partie individuelle — Présentation orale (20 %)&quot;">​</a></h2><h3 id="_7-communication-et-participation-a-l-oral-20" tabindex="-1">7) Communication et participation à l’oral (20 %) <a class="header-anchor" href="#_7-communication-et-participation-a-l-oral-20" aria-label="Permalink to &quot;7) Communication et participation à l’oral (20 %)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Niveau</th><th>Description</th><th>Note</th></tr></thead><tbody><tr><td><strong>Excellent</strong></td><td>Explication claire et structurée; bonne gestion du temps; ne lit pas les diapositives; maîtrise du sujet; participation visible et pertinente.</td><td>100 %</td></tr><tr><td><strong>Bien</strong></td><td>Présentation claire; quelques lectures/accrocs; gestion du temps globalement adéquate; participation satisfaisante.</td><td>80 %</td></tr><tr><td><strong>Suffisant</strong></td><td>Présentation fonctionnelle, mais lecture fréquente ou manque de clarté; gestion du temps ou participation inégale.</td><td>60 %</td></tr><tr><td><strong>Insuffisant</strong></td><td>Présentation peu claire; lecture dominante; difficultés à expliquer/justifier; participation très limitée.</td><td>40 %</td></tr><tr><td><strong>Invalide</strong></td><td>Aucune participation à l’oral.</td><td>0 %</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Si un membre ne prend pas la parole lors de la présentation, la note <strong>Invalide (0 %)</strong> s&#39;applique pour ce critère. Si un membre est <strong>absent</strong> à la présentation, la note de <strong>0 % s&#39;applique à l&#39;ensemble de l&#39;évaluation</strong>.</p></div><hr><h2 id="respect-des-consignes-et-modalites-de-remise-penalite" tabindex="-1">Respect des consignes et modalités de remise (pénalité) <a class="header-anchor" href="#respect-des-consignes-et-modalites-de-remise-penalite" aria-label="Permalink to &quot;Respect des consignes et modalités de remise (pénalité)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Situation observée</th><th>Pénalité appliquée</th></tr></thead><tbody><tr><td>Toutes les consignes sont respectées</td><td><strong>0 %</strong></td></tr><tr><td>Oublis mineurs ou non-respect partiel des consignes</td><td><strong>−5 %</strong></td></tr><tr><td>Non-respect important des consignes ou remise inadéquate</td><td><strong>−10 %</strong></td></tr></tbody></table><hr><h2 id="retard-dans-la-remise-de-la-presentation-sur-lea-penalite" tabindex="-1">Retard dans la remise de la présentation sur Léa (pénalité) <a class="header-anchor" href="#retard-dans-la-remise-de-la-presentation-sur-lea-penalite" aria-label="Permalink to &quot;Retard dans la remise de la présentation sur Léa (pénalité)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Retard observé</th><th>Pénalité appliquée</th></tr></thead><tbody><tr><td>≤ 24 h</td><td><strong>−10 %</strong></td></tr><tr><td>≤ 48 h</td><td><strong>−20 %</strong></td></tr><tr><td>≤ 72 h</td><td><strong>−30 %</strong></td></tr><tr><td>Plus de 72 h</td><td><strong>Travail refusé</strong></td></tr></tbody></table>',33)])])}const g=e(a,[["render",s]]);export{h as __pageData,g as default};
